export const INITIAL_SEED_QUESTIONS: SeedQuestion[] = [
  ...seedChunk_1, ...seedChunk_2, ...seedChunk_3, ...seedChunk_4, ...seedChunk_5, ...seedChunk_6, ...seedChunk_7, ...seedChunk_8, ...seedChunk_9, ...seedChunk_10
];

export function shuffleQuestionOptions(q: SeedQuestion): SeedQuestion {
  if (!q.options || q.options.length === 0) return q;

  let opts = [...q.options];
  const hasExactAnswer = opts.some(o => o === q.correctAnswer);
  if (!hasExactAnswer) {
    opts[0] = q.correctAnswer;
  }

  const uniqueOpts: string[] = [];
  opts.forEach(opt => {
    if (!uniqueOpts.includes(opt)) {
      uniqueOpts.push(opt);
    }
  });

  const shuffled = [...uniqueOpts];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const temp = shuffled[i];
    shuffled[i] = shuffled[j];
    shuffled[j] = temp;
  }

  return {
    ...q,
    options: shuffled,
    correctAnswer: q.correctAnswer,
  };
}
